from z3 import *

def find_bipartite(a, b, min_edges=28):
    # vertices 0..a-1 on left, a..a+b-1 on right
    n = a + b
    X = {}
    s = Optimize()
    # variables for cross edges only
    for i in range(a):
        for j in range(a, n):
            X[(i,j)] = Bool(f"x_{i}_{j}")
    # no C4: for any two left i1<i2 and two right j1<j2
    for i1 in range(a):
        for i2 in range(i1+1, a):
            for j1 in range(a, n):
                for j2 in range(j1+1, n):
                    s.add(Or(Not(X[(i1,j1)]), Not(X[(i2,j1)]), Not(X[(i2,j2)]), Not(X[(i1,j2)])))
    # maximize edges
    edge_vars = list(X.values())
    s.maximize(Sum([If(v,1,0) for v in edge_vars]))
    if s.check() == sat:
        m = s.model()
        edges = []
        for (i,j), v in X.items():
            if m.evaluate(v):
                edges.append((i,j))
        return edges
    else:
        return None

