import random

def has_c4(edges, a, n):
    # edges is list of (u,v) with u in [0,a), v in [a,n)
    # check for C4: two left vertices with two common neighbors
    from collections import defaultdict
    neighbors = defaultdict(set)
    for u, v in edges:
        neighbors[u].add(v)
    left = [u for u in range(a)]
    for i in range(len(left)):
        for j in range(i+1, len(left)):
            u1, u2 = left[i], left[j]
            common = neighbors[u1] & neighbors[u2]
            if len(common) >= 2:
                return True
    return False

def try_random(a, b, target_edges=28, max_iter=100000):
    n = a + b
    left = list(range(a))
    right = list(range(a, n))
    for _ in range(max_iter):
        # generate random bipartite graph with roughly target_edges edges
        possible = [(u, v) for u in left for v in right]
        # sample without replacement
        edges = random.sample(possible, min(target_edges, len(possible)))
        if not has_c4(edges, a, n) and len(edges) >= target_edges:
            return edges
    return None

