def greedy_bipartite(a, b, target=28):
    n = a + b
    left = list(range(a))
    right = list(range(a, n))
    edges = set()
    # adjacency
    adj_left = {u: set() for u in left}
    adj_right = {v: set() for v in right}

    possible = [(u, v) for u in left for v in right]
    random.shuffle(possible)

    for u, v in possible:
        # check if adding (u,v) creates C4
        # C4 would be u, v, u2, v2 where u2 in adj_right[v] and v2 in adj_left[u]
        # and u2 != u, v2 != v, and (u2, v2) in edges
        creates_c4 = False
        for u2 in adj_right[v]:
            if u2 == u:
                continue
            for v2 in adj_left[u]:
                if v2 == v:
                    continue
                if (u2, v2) in edges:
                    creates_c4 = True
                    break
            if creates_c4:
                break

        if not creates_c4:
            edges.add((u, v))
            adj_left[u].add(v)
            adj_right[v].add(u)
            if len(edges) >= target:
                return list(edges)

    return list(edges) if len(edges) >= target else None

random.seed(42)
for a in range(1, 17):
