        if edges and len(edges) >= 28:
            print(f"Success with partition ({a},{b}): {len(edges)} edges")
            print(edges)
            raise SystemExit
    # print progress
    if a % 3 == 0:
        print(f"Tried up to partition ({a},{b})")

